# Generated by scripts/install-script-generated.mjs from
# config/portable-server-node-runtime.json. Do not edit by hand. The official
# Node.js distribution for win32-x64, pinned by digest.
$PinnedNodeVersion = '24.21.0'
$PinnedNodeOrigin = 'https://nodejs.org/dist/v24.21.0/'
$PinnedNodeFile = 'node-v24.21.0-win-x64.zip'
$PinnedNodeEntry = 'node-v24.21.0-win-x64/node.exe'
